window.AUTH=window.AUTH||{};window.AUTH["21-86"]={"d":"21-86","id":"2022/21-86","n":"Axon Enterprise, Inc. v. Federal Trade Commission","briefs":[{"k":"petitioner","label":"Brief of petitioner Axon Enterprise, Inc.","date":"2022-05-09","url":"https://www.supremecourt.gov/DocketPDF/21/21-86/222777/20220509120815179_2022-05-09%20FINAL%20Axon%20Opening%20Brief.pdf","side":"pet","n":58},{"k":"reply","label":"Reply of petitioner Axon Enterprise, Inc.","date":"2022-09-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-86/237236/20220907132731177_21-86%20Axon%20Merits%20Reply%20Final.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r10_febh.pdf","tr":true,"items":[{"t":"case","label":"AMG Cap. Mgmt., LLC v. FTC","cite":"141 S. Ct. 1341","y":2021,"id":"2020/19-508","sc":1,"sum":"Section 13(b) of the Federal Trade Commission Act does not authorize the Commission to seek, or a court to award, equitable monetary relief such as restitution or disgorgement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11","1":"15"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"op":4,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"4, 23","1":"16"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 23","1":"19"}},{"t":"case","label":"Bennett v. SEC","cite":"844 F.3d 174","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/174/","by":{"0":"15"}},{"t":"case","label":"Bond v. United States","cite":"564 U.S. 211","y":2011,"id":"2010/09-1227","sc":1,"sum":"The Court held that a defendant, convicted under a federal statute, has a right to challenge his/her conviction based on the unconstitutionality of the statute.","sumSrc":"Oyez","by":{"0":"23, 47","1":"17, 19"}},{"t":"case","label":"Bowen v. Mich. Acad. of Fam. Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 24"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"23, 35, 47"}},{"t":"case","label":"Carr v. Saul","cite":"141 S. Ct. 1352","y":2021,"id":"2020/19-1442","sc":1,"op":1,"sum":"Principles of issue-exhaustion do not require Social Security disability claimants to argue at the agency level that the administrative law judges hearing their disability claims were unconstitutionally appointed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34, 38"}},{"t":"case","label":"Cochran v. SEC","cite":"20 F.4th 194","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/20/194/","op":72,"ar":1,"by":{"0":"19","1":"15"}},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49","1":"23"}},{"t":"case","label":"Colo. River Water Conservation Dist. v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Elgin v. Dep’t of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"op":19,"ar":16,"sum":"Holding that Congress provided “meaningful review” in authorizing the Federal Circuit “to consider and decide petitioners' constitutional claims”.","sumSrc":"opinion","by":{"0":"passim","1":"5, 6, 12"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":23,"ar":19,"sum":"Noting that statutory schemes for agency review “[g]enerally” are “exclusive”.","sumSrc":"opinion","by":{"0":"passim","1":"passim"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","y":1974,"id":"1973/72-1297","sc":1,"sum":"Appellee, who had been exempted from military service as a Class 1-0 conscientious objector bo. who perfurmed required alternative civilian service, after being denied educational benefits under the Veterans' Readjustmcnt Benefits Act of 1966 brought this class action for a declaratory judgment that' the provisions of the Act making him and his class ineligible for such benefits violated the First Amendment's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 24"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"op":4,"ar":2,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"0":"10, 13, 48, 49","1":"19"}},{"t":"case","label":"Mata v. Lynch","cite":"576 U.S. 143","y":2015,"id":"2014/14-185","sc":1,"sum":"The Court held that circuit courts of appeals have jurisdiction over Board of Immigration Appeals decisions to deny motions to reopen immigration proceedings.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"ar":4,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"ar":2,"sum":"The District Court had federal-question jurisdiction to hear respondents' constitutional and statutory challenges to the INS procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 41, 42"}},{"t":"case","label":"Roman Cath. Diocese of Brooklyn v. Cuomo","cite":"141 S. Ct. 63","y":2020,"id":"2020/20a87","sc":1,"sum":"Respondent is enjoined from enforcing Executive Order 202.68’s 10- and 25-person occupancy limits on Applicant pending disposition of the appeal in the United States Court of Appeals for the Second Circuit and disposition of the petition for a writ of certiorari, if such writ is timely sought.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 36"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"op":2,"ar":2,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"0":"passim","1":"7, 19"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"op":56,"ar":25,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"5, 6"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"141 S. Ct. 1970","y":2021,"id":"2020/19-1434","sc":1,"ar":1,"sum":"The unreviewable authority wielded by Administrative Patent Judges during inter partes review is incompatible with their appointment by the Secretary of Commerce to an inferior office; the judgment of the Federal Circuit is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49"}},{"t":"case","label":"Verizon Md. Inc. v. Pub. Serv. Comm’n of Md.","cite":"535 U.S. 635","y":2002,"id":"2001/00-1531","sc":1,"sum":"The Court held that the district court had jurisdiction, so as to review the Commission's order for compliance with federal law, to entertain the suit because resolution of the LEC's claim turned on whether the Act, or an FCC ruling issued thereunder, precluded the state commission from ordering payment of reciprocal compensation.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 24"}},{"t":"case","label":"Whitman v. Dep’t of Transp.","cite":"547 U.S. 512","y":2006,"id":"2005/04-1131","sc":1,"sum":"The Justices declined to rule on whether the District Court should have taken Whitman's case, because lower courts had not determined exactly \"where Whitman's claims fit within the statutory scheme.\" The Court sent the case back to the Court of Appeals with instructions to rule on this question. (Justice Alito took no part in the decision of this case.).","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Whitney Nat’l Bank in Jefferson Parish v. Bank of New Orleans & Trust Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"sum":"A New Orleans-based national bank, desiring to expand but prohibited from operating branches beyond its home parish, formed a holding company which in turn organized a new national bank to operate in an adjoining parish. Pursuant to the Bank Holding Company Act of 1956, the Federal Reserve Board (FRB), after receiving favorable advice from the Comptroller of the Currency (Comptroller), held hearings on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"usc","label":"5 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/5/1202","subs":["(d)"],"by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/5/7521","subs":["(a)"],"stext":{"head":"§7521. Actions against administrative law judges","paras":[[0,"(a) An action may be taken against an administrative law judge appointed under section 3105 of this title by the agency in which the administrative law judge is employed only for good cause established and determined by the Merit Systems Protection Board on the record after opportunity for hearing before the Board."],[0,"(b) The actions covered by this section are—"],[1,"(1) a removal;"],[1,"(2) a suspension;"],[1,"(3) a reduction in grade;"],[1,"(4) a reduction in pay; and"],[1,"(5) a furlough of 30 days or less;"],[0,"but do not include—"],[1,"(A) a suspension or removal under section 7532 of this title;"],[1,"(B) a reduction-in-force action under section 3502 of this title; or"],[1,"(C) any action initiated under section 1215 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7521?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7521. Actions against administrative law judges","tname":"Government Organization and Employees","by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(d)"],"by":{"0":"11, 32"}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","subs":["(i)"],"stext":{"head":"§1818. Termination of status as insured depository institution","paras":[[0,"(a) Termination of insurance"],[0,"(1) Voluntary termination"],[1,"Any insured depository institution which is not—"],[2,"(A) a national member bank;"],[2,"(B) a State member bank;"],[2,"(C) a Federal branch;"],[2,"(D) a Federal savings association; or"],[2,"(E) an insured branch which is required to be insured under subsection (a) or (b) 1 of section 3104 of this title,"],[1,"may terminate such depository institution's status as an insured depository institution if such insured institution provides written notice to the Corporation of the institution's intent to terminate such status not less than 90 days before the effective date of such termination."],[0,"(2) Involuntary termination"],[0,"(A) Notice to primary regulator"],[2,"If the Board of Directors determines that—"],[3,"(i) an insured depository institution or the directors or trustees of an insured depository institution have engaged or are engaging in unsafe or unsound practices in conducting the business of the depository institution;"],[3,"(ii) an insured depository institution is in an unsafe or unsound condition to continue operations as an insured institution; or"],[3,"(iii) an insured depository institution or the directors or trustees of the insured institution have violated any applicable law, regulation, order, condition imposed in writing by the Corporation in connection with the approval of any application or other request by the insured depository institution, or written agreement entered into between the insured depository institution and the Corporation,"],[2,"the Board of Directors shall notify the appropriate Federal banking agency with respect to such institution (if other than the Corporation) or the State banking supervisor of such institution (if the Corporation is the appropriate Federal banking agency) of the Board's determination and the facts and circumstances on which such determination is based for the purpose of securing the correction of such practice, condition, or violation. Such notice shall be given to the appropriate Federal banking agency not less than 30 days before the notice required by subparagraph (B), except that this period for notice to the appropriate Federal banking agency may be reduced or eliminated with the agreement of such agency."],[0,"(B) Notice of intention to terminate insurance"],[2,"If, after giving the notice required under subparagraph (A) with respect to an insured depository institution, the Board of Directors determines that any unsafe or unsound practice or condition or any violation specified in such notice requires the termination of the insured status of the insured depository institution, the Board shall—"],[3,"(i) serve written notice to the insured depository institution of the Board's intention to terminate the insured status of the institution;"],[3,"(ii) provide the insured depository institution with a statement of the charges on the basis of which the determination to terminate such institution's insured status was made (or a copy of the notice under subparagraph (A)); and"],[3,"(iii) notify the insured depository institution of the date (not less than 30 days after notice under this subparagraph) and place for a hearing before the Board of Directors (or any person designated by the Board) with respect to the termination of the institution's insured status."],[0,"(3) Hearing; termination"],[1,"If, on the basis of the evidence presented at a hearing before the Board of Directors (or any person designated by the Board for such purpose), in which all issues shall be determined on the record pursuant to section 554 of title 5 and the written findings of the Board of Directors (or such person) with respect to such evidence (which shall be conclusive), the Board of Directors finds that any unsafe or unsound practice or condition or any violation specified in the notice to an insured depository institution under paragraph (2)(B) or subsection (w) has been established, the Board of Directors may issue an order terminating the insured status of such depository institution effective as of a date subsequent to such finding."],[0,"(4) Appearance; consent to termination"],[1,"Unless the depository institution shall appear at the hearing by a duly authorized representative, it shall be deemed to have consented to the termination of its status as an insured depository institution and termination of such status thereupon may be ordered."],[0,"(5) Judicial review"],[1,"Any insured depository institution whose insured status has been terminated by order of the Board of Directors under this subsection shall have the right of judicial review of such order only to the same extent as provided for the review of orders under subsection (h) of this section."],[0,"(6) Publication of notice of termination"],[1,"The Corporation may publish notice of such termination and the depository institution shall give notice of such termination to each of its depositors at his last address of record on the books of the depository institution, in such manner and at such time as the Board of Directors may find to be necessary and may order for the protection of depositors."],[0,"(7) Temporary insurance of deposits insured as of termination"],[1,"After the termination of the insured status of any depository institution under the provisions of this subsection, the insured deposits of each depositor in the depository institution on the date of such termination, less all subsequent withdrawals from any deposits of such depositor, shall continue for a period of at least 6 months or up to 2 years, within the discretion of the Board of Directors, to be insured, and the depository institution shall continue to pay to the Corporation assessments as in the case of an insured depository institution during such period. No additions to any such deposits and no new deposits in such depository institution made after the date of such termination shall be insured by the Corporation, and the depository institution shall not advertise or hold itself out as having insured deposits unless in the same connection it shall also state with equal prominence that such additions to deposits and new deposits made after such date are not so insured. Such depository institution shall, in all other respects, be subject to the duties and obligations of an insured depository institution for the period referred to in the 1st sentence from the date of such termination, and in the event that such depository institution shall be closed on account of inability to meet the demands of its depositors within such period, the Corporation shall have the same powers and rights with respect to such depository institution as in case of an insured depository institution."],[0,"(8) Temporary suspension of insurance"],[0,"(A) In general"],[2,"If the Board of Directors initiates a termination proceeding under paragraph (2), and the Board of Directors, after consultation with the appropriate Federal banking agency, finds that an insured depository institution (other than a savings association to which subparagraph (B) applies) has no tangible capital under the capital guidelines or regulations of the appropriate Federal banking agency, the Corporation may issue a temporary order suspending deposit insurance on all deposits received by the institution."],[0,"(B) Special rule for certain savings institutions"],[0,"(i) Certain goodwill included in tangible capital"],[3,"In determining the tangible capital of a savings association for purposes of this paragraph, the Board of Directors shall include goodwill to the extent it is considered a component of capital under section 1464(t) of this title. Any savings association which would be subject to a suspension order under subparagraph (A) but for the operation of this subparagraph, shall be considered by the Corporation to be a \"special supervisory association\"."],[0,"(ii) Suspension order"],[3,"The Corporation may issue a temporary order suspending deposit insurance on all deposits received by a special supervisory association whenever the Board of Directors determines that—"],[4,"(I) the capital of such association, as computed utilizing applicable accounting standards, has suffered a material decline;"],[4,"(II) that such association (or its directors or officers) is engaging in an unsafe or unsound practice in conducting the business of the association;"],[4,"(III) that such association is in an unsafe or unsound condition to continue operating as an insured association; or"],[4,"(IV) that such association (or its directors or officers) has violated any applicable law, rule, regulation, or order, or any condition imposed in writing by a Federal banking agency, or any written agreement including a capital improvement plan entered into with any Federal banking agency, or that the association has failed to enter into a capital improvement plan which is acceptable to the Corporation within the time period set forth in section 1464(t) of this title."],[0,"Nothing in this paragraph limits the right of the Corporation or the Comptroller of the Currency to enforce a contractual provision which authorizes the Corporation or the Comptroller of the Currency, as a successor to the Federal Savings and Loan Insurance Corporation or the Federal Home Loan Bank Board, to require a savings association to write down or amortize goodwill at a faster rate than otherwise required under this chapter or under applicable accounting standards."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1818?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1818. Termination of status as insured depository institution","tname":"Banks and Banking","by":{"0":"24"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","stext":{"head":"§41. Federal Trade Commission established; membership; vacancies; seal","paras":[[0,"A commission is created and established, to be known as the Federal Trade Commission (hereinafter referred to as the Commission), which shall be composed of five Commissioners, who shall be appointed by the President, by and with the advice and consent of the Senate. Not more than three of the Commissioners shall be members of the same political party. The first Commissioners appointed shall continue in office for terms of three, four, five, six, and seven years, respectively, from September 26, 1914, the term of each to be designated by the President, but their successors shall be appointed for terms of seven years, except that any person chosen to fill a vacancy shall be appointed only for the unexpired term of the Commissioner whom he shall succeed: Provided, however, That upon the expiration of his term of office a Commissioner shall continue to serve until his successor shall have been appointed and shall have qualified..1 The President shall choose a chairman from the Commission's membership. No Commissioner shall engage in any other business, vocation, or employment. Any Commissioner may be removed by the President for inefficiency, neglect of duty, or malfeasance in office. A vacancy in the Commission shall not impair the right of the remaining Commissioners to exercise all the powers of the Commission."],[0,"The Commission shall have an official seal, which shall be judicially noticed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/41?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§41. Federal Trade Commission established; membership; vacancies; seal","tname":"Commerce and Trade","by":{"0":"7"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(a)","(b)","(c)","(d)","(g)"],"stext":{"head":"§45. Unfair methods of competition unlawful; prevention by Commission","paras":[[0,"(a) Declaration of unlawfulness; power to prohibit unfair practices; inapplicability to foreign trade"],[0,"(1) Unfair methods of competition in or affecting commerce, and unfair or deceptive acts or practices in or affecting commerce, are hereby declared unlawful."],[0,"(2) The Commission is hereby empowered and directed to prevent persons, partnerships, or corporations, except banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, common carriers subject to the Acts to regulate commerce, air carriers and foreign air carriers subject to part A of subtitle VII of title 49, and persons, partnerships, or corporations insofar as they are subject to the Packers and Stockyards Act, 1921, as amended [7 U.S.C. 181 et seq.], except as provided in section 406(b) of said Act [7 U.S.C. 227(b)], from using unfair methods of competition in or affecting commerce and unfair or deceptive acts or practices in or affecting commerce."],[0,"(3) This subsection shall not apply to unfair methods of competition involving commerce with foreign nations (other than import commerce) unless—"],[1,"(A) such methods of competition have a direct, substantial, and reasonably foreseeable effect—"],[2,"(i) on commerce which is not commerce with foreign nations, or on import commerce with foreign nations; or"],[2,"(ii) on export commerce with foreign nations, of a person engaged in such commerce in the United States; and"],[1,"(B) such effect gives rise to a claim under the provisions of this subsection, other than this paragraph."],[0,"If this subsection applies to such methods of competition only because of the operation of subparagraph (A)(ii), this subsection shall apply to such conduct only for injury to export business in the United States."],[0,"(4)(A) For purposes of subsection (a), the term \"unfair or deceptive acts or practices\" includes such acts or practices involving foreign commerce that—"],[1,"(i) cause or are likely to cause reasonably foreseeable injury within the United States; or"],[1,"(ii) involve material conduct occurring within the United States."],[0,"(B) All remedies available to the Commission with respect to unfair and deceptive acts or practices shall be available for acts and practices described in this paragraph, including restitution to domestic or foreign victims."],[0,"(b) Proceeding by Commission; modifying and setting aside orders"],[0,"Whenever the Commission shall have reason to believe that any such person, partnership, or corporation has been or is using any unfair method of competition or unfair or deceptive act or practice in or affecting commerce, and if it shall appear to the Commission that a proceeding by it in respect thereof would be to the interest of the public, it shall issue and serve upon such person, partnership, or corporation a complaint stating its charges in that respect and containing a notice of a hearing upon a day and at a place therein fixed at least thirty days after the service of said complaint. The person, partnership, or corporation so complained of shall have the right to appear at the place and time so fixed and show cause why an order should not be entered by the Commission requiring such person, partnership, or corporation to cease and desist from the violation of the law so charged in said complaint. Any person, partnership, or corporation may make application, and upon good cause shown may be allowed by the Commission to intervene and appear in said proceeding by counsel or in person. The testimony in any such proceeding shall be reduced to writing and filed in the office of the Commission. If upon such hearing the Commission shall be of the opinion that the method of competition or the act or practice in question is prohibited by this subchapter, it shall make a report in writing in which it shall state its findings as to the facts and shall issue and cause to be served on such person, partnership, or corporation an order requiring such person, partnership, or corporation to cease and desist from using such method of competition or such act or practice. Until the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, or, if a petition for review has been filed within such time then until the record in the proceeding has been filed in a court of appeals of the United States, as hereinafter provided, the Commission may at any time, upon such notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any report or any order made or issued by it under this section. After the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, the Commission may at any time, after notice and opportunity for hearing, reopen and alter, modify, or set aside, in whole or in part any report or order made or issued by it under this section, whenever in the opinion of the Commission conditions of fact or of law have so changed as to require such action or if the public interest shall so require, except that (1) the said person, partnership, or corporation may, within sixty days after service upon him or it of said report or order entered after such a reopening, obtain a review thereof in the appropriate court of appeals of the United States, in the manner provided in subsection (c) of this section; and (2) in the case of an order, the Commission shall reopen any such order to consider whether such order (including any affirmative relief provision contained in such order) should be altered, modified, or set aside, in whole or in part, if the person, partnership, or corporation involved files a request with the Commission which makes a satisfactory showing that changed conditions of law or fact require such order to be altered, modified, or set aside, in whole or in part. The Commission shall determine whether to alter, modify, or set aside any order of the Commission in response to a request made by a person, partnership, or corporation under paragraph 1 (2) not later than 120 days after the date of the filing of such request."],[0,"(c) Review of order; rehearing"],[0,"Any person, partnership, or corporation required by an order of the Commission to cease and desist from using any method of competition or act or practice may obtain a review of such order in the court of appeals of the United States, within any circuit where the method of competition or the act or practice in question was used or where such person, partnership, or corporation resides or carries on business, by filing in the court, within sixty days from the date of the service of such order, a written petition praying that the order of the Commission be set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Commission, and thereupon the Commission shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon such filing of the petition the court shall have jurisdiction of the proceeding and of the question determined therein concurrently with the Commission until the filing of the record and shall have power to make and enter a decree affirming, modifying, or setting aside the order of the Commission, and enforcing the same to the extent that such order is affirmed and to issue such writs as are ancillary to its jurisdiction or are necessary in its judgement to prevent injury to the public or to competitors pendente lite. The findings of the Commission as to the facts, if supported by evidence, shall be conclusive. To the extent that the order of the Commission is affirmed, the court shall thereupon issue its own order commanding obedience to the terms of such order of the Commission. If either party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts, or make new findings, by reason of the additional evidence so taken, and it shall file such modified or new findings, which, if supported by evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of its original order, with the return of such additional evidence. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court upon certiorari, as provided in section 1254 of title 28."],[0,"(d) Jurisdiction of court"],[0,"Upon the filing of the record with it the jurisdiction of the court of appeals of the United States to affirm, enforce, modify, or set aside orders of the Commission shall be exclusive."],[0,"(e) Exemption from liability"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/45?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§45. Unfair methods of competition unlawful; prevention by Commission","tname":"Commerce and Trade","by":{"0":"7, 8, 10, 31, 11, 31, 33, 38, 11, 32, 11"}},{"t":"usc","label":"15 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/15/46","subs":["(d)","(e)","(k)"],"by":{"0":"8, 8, 8"}},{"t":"usc","label":"15 U.S.C. § 53","url":"https://www.law.cornell.edu/uscode/text/15/53","subs":["(b)"],"by":{"0":"11, 20, 31"}},{"t":"usc","label":"15 U.S.C. § 7217","url":"https://www.law.cornell.edu/uscode/text/15/7217","subs":["(b)","(c)"],"by":{"0":"27, 27"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)"],"stext":{"head":"§78y. Court review of orders and rules","paras":[[0,"(a) Final Commission orders; persons aggrieved; petition; record; findings; affirmance, modification, enforcement, or setting aside of orders; remand to adduce additional evidence"],[0,"(1) A person aggrieved by a final order of the Commission entered pursuant to this chapter may obtain review of the order in the United States Court of Appeals for the circuit in which he resides or has his principal place of business, or for the District of Columbia Circuit, by filing in such court, within sixty days after the entry of the order, a written petition requesting that the order be modified or set aside in whole or in part."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated by the Commission for that purpose. Thereupon the Commission shall file in the court the record on which the order complained of is entered, as provided in section 2112 of title 28 and the Federal Rules of Appellate Procedure."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the record, to affirm or modify and enforce or to set aside the order in whole or in part."],[0,"(4) The findings of the Commission as to the facts, if supported by substantial evidence, are conclusive."],[0,"(5) If either party applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there was reasonable ground for failure to adduce it before the Commission, the court may remand the case to the Commission for further proceedings, in whatever manner and on whatever conditions the court considers appropriate. If the case is remanded to the Commission, it shall file in the court a supplemental record containing any new evidence, any further or modified findings, and any new order."],[0,"(b) Commission rules; persons adversely affected; petition; record; affirmance, enforcement, or setting aside of rules; findings; transfer of proceedings"],[0,"(1) A person adversely affected by a rule of the Commission promulgated pursuant to section 78f, 78i(h)(2), 78k, 78k–1, 78o(c)(5) or (6), 78o–3, 78q, 78q–1, or 78s of this title may obtain review of this rule in the United States Court of Appeals for the circuit in which he resides or has his principal place of business or for the District of Columbia Circuit, by filing in such court, within sixty days after the promulgation of the rule, a written petition requesting that the rule be set aside."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated for that purpose. Thereupon, the Commission shall file in the court the rule under review and any documents referred to therein, the Commission's notice of proposed rulemaking and any documents referred to therein, all written submissions and the transcript of any oral presentations in the rulemaking, factual information not included in the foregoing that was considered by the Commission in the promulgation of the rule or proffered by the Commission as pertinent to the rule, the report of any advisory committee received or considered by the Commission in the rulemaking, and any other materials prescribed by the court."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the materials set forth in paragraph (2) of this subsection, to affirm and enforce or to set aside the rule."],[0,"(4) The findings of the Commission as to the facts identified by the Commission as the basis, in whole or in part, of the rule, if supported by substantial evidence, are conclusive. The court shall affirm and enforce the rule unless the Commission's action in promulgating the rule is found to be arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law; contrary to constitutional right, power, privilege, or immunity; in excess of statutory jurisdiction, authority, or limitations, or short of statutory right; or without observance of procedure required by law."],[0,"(5) If proceedings have been instituted under this subsection in two or more courts of appeals with respect to the same rule, the Commission shall file the materials set forth in paragraph (2) of this subsection in that court in which a proceeding was first instituted. The other courts shall thereupon transfer all such proceedings to the court in which the materials have been filed. For the convenience of the parties in the interest of justice that court may thereafter transfer all the proceedings to any other court of appeals."],[0,"(c) Objections not urged before Commission; stay of orders and rules; transfer of enforcement or review proceedings"],[0,"(1) No objection to an order or rule of the Commission, for which review is sought under this section, may be considered by the court unless it was urged before the Commission or there was reasonable ground for failure to do so."],[0,"(2) The filing of a petition under this section does not operate as a stay of the Commission's order or rule. Until the court's jurisdiction becomes exclusive, the Commission may stay its order or rule pending judicial review if it finds that justice so requires. After the filing of a petition under this section, the court, on whatever conditions may be required and to the extent necessary to prevent irreparable injury, may issue all necessary and appropriate process to stay the order or rule or to preserve status or rights pending its review; but (notwithstanding section 705 of title 5) no such process may be issued by the court before the filing of the record or the materials set forth in subsection (b)(2) of this section unless: (A) the Commission has denied a stay or failed to grant requested relief, (B) a reasonable period has expired since the filing of an application for a stay without a decision by the Commission, or (C) there was reasonable ground for failure to apply to the Commission."],[0,"(3) When the same order or rule is the subject of one or more petitions for review filed under this section and an action for enforcement filed in a district court of the United States under section 78u(d) or (e) of this title, that court in which the petition or the action is first filed has jurisdiction with respect to the order or rule to the exclusion of any other court, and thereupon all such proceedings shall be transferred to that court; but, for the convenience of the parties in the interest of justice, that court may thereafter transfer all the proceedings to any other court of appeals or district court of the United States, whether or not a petition for review or an action for enforcement was originally filed in the transferee court. The scope of review by a district court under section 78u(d) or (e) of this title is in all cases the same as by a court of appeals under this section."],[0,"(d) Other appropriate regulatory agencies"],[0,"(1) For purposes of the preceding subsections of this section, the term \"Commission\" includes the agencies enumerated in section 78c(a)(34) of this title insofar as such agencies are acting pursuant to this chapter and the Secretary of the Treasury insofar as he is acting pursuant to section 78o–5 of this title."],[0,"(2) For purposes of subsection (a)(4) of this section and section 706 of title 5, an order of the Commission pursuant to section 78s(a) of this title denying registration to a clearing agency for which the Commission is not the appropriate regulatory agency or pursuant to section 78s(b) of this title disapproving a proposed rule change by such a clearing agency shall be deemed to be an order of the appropriate regulatory agency for such clearing agency insofar as such order was entered by reason of a determination by such appropriate regulatory agency pursuant to section 78s(a)(2)(C) or 78s(b)(4)(C) of this title that such registration or proposed rule change would be inconsistent with the safeguarding of securities or funds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78y?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§78y. Court review of orders and rules","tname":"Commerce and Trade","by":{"0":"27, 11, 32"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":15,"ar":1,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"0":"4, 22"}},{"t":"usc","label":"30 U.S.C. § 816","url":"https://www.law.cornell.edu/uscode/text/30/816","subs":["(a)"],"by":{"0":"11, 33"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)"],"by":{"0":"24"}},{"t":"reg","label":"16 C.F.R. § 0.1","url":"https://www.ecfr.gov/current/title-16/section-0.1","by":{"0":"7"}},{"t":"reg","label":"16 C.F.R. § 0.14","url":"https://www.ecfr.gov/current/title-16/section-0.14","by":{"0":"9"}},{"t":"reg","label":"16 C.F.R. § 3.11","url":"https://www.ecfr.gov/current/title-16/section-3.11","by":{"0":"8"}},{"t":"reg","label":"16 C.F.R. § 3.22-26","url":"https://www.ecfr.gov/current/title-16/section-3.22-26","by":{"0":"10"}},{"t":"reg","label":"16 C.F.R. § 3.41-46","url":"https://www.ecfr.gov/current/title-16/section-3.41-46","by":{"0":"10"}},{"t":"reg","label":"16 C.F.R. § 3.42","url":"https://www.ecfr.gov/current/title-16/section-3.42","subs":["(a)","(d)"],"by":{"0":"9, 10"}},{"t":"reg","label":"16 C.F.R. § 3.51","url":"https://www.ecfr.gov/current/title-16/section-3.51","by":{"0":"10"}},{"t":"reg","label":"16 C.F.R. § 3.54","url":"https://www.ecfr.gov/current/title-16/section-3.54","by":{"0":"10"}},{"t":"reg","label":"16 C.F.R. § 3.56","url":"https://www.ecfr.gov/current/title-16/section-3.56","by":{"0":"10"}},{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"sum":"Petitioners and others were charged in a single-count indictment with conspiracy and an attempt to obstruct interstate commerce by means of extortion, in violation of the Hobbs Act. Petitioners challenged the indictment as duplicitous, contending that its single count improperly charged both a conspiracy and an attempt to violate the Hobbs Act. The District Court refused to dismiss the indictment but required the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 11"}},{"t":"case","label":"Am. Sch. of Magnetic Healing v. McAnnulty","cite":"187 U.S. 94","y":1902,"id":"scdb/1902-027","sc":1,"sum":"On demurrer all the material facts averred in a bill of complaint are admitted, including averments describing complainant’s business and stating that it is founded “almost exclusively on the physical and practical proposition that the mind of the human race is largely responsiblefor its ills, ahd Js.a perceptible factor in the healing, curing, benefiting and' remedying thereof, and that the human race does possess …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19, 22"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Doe Co. v. CFPB","cite":"849 F.3d 1129","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1129/","by":{"1":"7"}},{"t":"case","label":"FTC v. Standard Oil Co.","cite":"449 U.S. 232","y":1980,"id":"1980/79-900","sc":1,"op":1,"ar":8,"sum":"The FTC's issuance of its complaint was not \"final agency action\" under § 10 (c) of the APA and hence was not judicially reviewable before the conclusion of the administrative adjudication.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"LabMD, Inc. v. FTC","cite":"2019 WL 11502794","y":2019,"court":"N.D. Ga. Oct. 1","by":{"1":"22"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Perkins v. Lukens Steel Co.","cite":"310 U.S. 113","y":1940,"id":"scdb/1939-044","sc":1,"sum":"The Publie Contract., Act of June 30, 1936, requires that all contrtcts with the United States for the manufacture or furnishing of materials (in amounts exceeding S10,000) shall include a -tipulation that all persons employed by the contractor in the manifacture or furnishing of such materials will be paid not less than the prevailing minimum wages \"as determined by the Secretary of Labor... for persons employed... …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Stark v. Wickard","cite":"321 U.S. 288","y":1944,"id":"scdb/1943-091","sc":1,"sum":"that the producers had standing to sue. Pp. 289, 305.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"sum":"The Court held that the All Writs Act does not provide removal jurisdiction.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"10"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","stext":{"head":"§703. Form and venue of proceeding","paras":[[0,"The form of proceeding for judicial review is the special statutory review proceeding relevant to the subject matter in a court specified by statute or, in the absence or inadequacy thereof, any applicable form of legal action, including actions for declaratory judgments or writs of prohibitory or mandatory injunction or habeas corpus, in a court of competent jurisdiction. If no special statutory review proceeding is applicable, the action for judicial review may be brought against the United States, the agency by its official title, or the appropriate officer. Except to the extent that prior, adequate, and exclusive opportunity for judicial review is provided by law, agency action is subject to judicial review in civil or criminal proceedings for judicial enforcement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/703?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§703. Form and venue of proceeding","tname":"Government Organization and Employees","by":{"1":"20"}},{"t":"usc","label":"28 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/28/1361","by":{"1":"8"}}]};